    assert myStringBuilder.length() >= myCurrentGroup.myStart;
    myCurrentGroup.myLength = myStringBuilder.length() - myCurrentGroup.myStart;
    myCurrentGroup = myCurrentGroup.myParent;
    return this;
  }

